Object.assign(module.exports, {
construction: [
['site-new-colleague',1,'Prima zi în echipă','Ești noul coleg Alex. Nora coordonează echipa. Prezintă-te și cere locul întâlnirii.','Jeg heter Alex og er ny i teamet.','Hvor skal vi møtes?','møtes ved kontoret','møtes ved inngangen','Er det ved kontoret vi møtes?','Ja, vi møtes der.'],
['site-storage-location',1,'Unde este depozitul?','Ești muncitorul. Nora este colega ta. Cauți depozitul, aflat lângă birou în această situație fictivă.','Jeg leter etter lageret.','Kan du vise meg veien?','se lageret på planen','følge Nora til lageret','Ligger lageret ved kontoret?','Ja, det ligger der.'],
['site-marked-box',1,'Cutia corectă','Ești muncitorul. Nora este colega ta. Ai nevoie de cutia marcată A, dar vezi cutiile A și B.','Jeg trenger kassen merket A.','Kan vi sjekke merkingen?','lese etiketten sammen','be Nora peke ut kasse A','Er denne merket A?','Ja, den er merket A.'],
['site-clothing-size',1,'Mărimea echipamentului','Ești noul coleg. Nora gestionează echipamentul. Ai primit mărimea M, dar ceri verificarea disponibilității L. Nu certifica potrivirea echipamentului.','Jeg har fått størrelse M.','Kan du sjekke om L finnes?','sjekke lagerlisten','spørre utstyrsansvarlig','Skal vi spørre ansvarlig først?','Ja, ansvarlig kan kontrollere tilgjengeligheten.'],
['site-start-time',2,'Ora întâlnirii de dimineață','Ești muncitorul. Nora coordonează întâlnirea. Sunt propuse orele 7 și 8; trebuie confirmată una.','Vi har to forslag, klokka sju og åtte.','Kan vi bekrefte møtetiden?','velge klokka sju','velge klokka åtte','Passer klokka åtte?','Ja, åtte passer.'],
['site-delivery-arrival',2,'Când vine livrarea?','Ești muncitorul. Nora coordonează livrarea. Marfa este anunțată pentru azi, fără oră confirmată.','Leveringen er meldt i dag, men tidspunktet er uklart.','Kan du undersøke ankomsten?','kontakte leverandøren','be om oppdatering når tiden er kjent','Har leverandøren bekreftet en tid?','Nei, ikke ennå.'],
['site-work-order',2,'Ordinea sarcinilor','Ești muncitorul. Nora coordonează echipa. Ai două sarcini administrative, A și B, fără ordine stabilită.','Jeg har oppgave A og B, men ingen avtalt rekkefølge.','Hvilken skal jeg begynne med?','avklare A som første oppgave','avklare B som første oppgave','Skal vi avklare rekkefølgen før start?','Ja, vi gjør det først.'],
['site-meeting-reschedule',2,'Mutarea discuției de echipă','Ești colegul Norei. Nu poți la discuția de la 10; ești liber la 12 sau 14.','Jeg kan ikke klokka ti, men er ledig tolv og fjorten.','Kan vi flytte samtalen?','møtes klokka tolv','møtes klokka fjorten','Passer fjorten for deg?','Ja, fjorten passer.'],
['site-drawing-version',3,'Două versiuni ale planului','Ești muncitorul. Nora coordonează documentele. Ai planurile V1 și V2 și nu știi care este aprobat.','Jeg har versjon én og to, men vet ikke hvilken som er godkjent.','Kan du avklare riktig versjon?','kontrollere dokumentlisten','spørre dokumentansvarlig','Er versjon to godkjent?','Det må kontrolleres.'],
['site-wrong-material',3,'Materialul nu corespunde','Ești muncitorul. Nora primește materialele. Lista cere tip A, iar eticheta livrării spune B.','Listen sier type A, men etiketten sier B.','Kan vi kontrollere leveringen?','sjekke bestillingen','kontakte leverandøren','Skal materialet vente på avklaring?','Ja, vi avklarer forskjellen først.'],
['site-damaged-tool',3,'O unealtă deteriorată','Ești muncitorul. Nora coordonează echipamentul. Observi o fisură pe carcasa unei unelte; nu o folosi și nu oferi reparații.','Jeg ser en sprekk i verktøyets deksel.','Kan du varsle utstyrsansvarlig?','registrere observasjonen','kontakte ansvarlig for vurdering','Skal jeg beskrive den synlige skaden?','Ja, beskriv det du ser.'],
['site-access-card',3,'Cardul nu deschide poarta','Ești muncitorul. Nora gestionează accesul. Cardul nu deschide poarta; cauza nu este cunoscută.','Adgangskortet åpner ikke porten.','Kan du undersøke tilgangen?','kontakte adgangsansvarlig','kontrollere kortregistreringen','Skal vi sjekke registreringen først?','Ja, det kan vi.'],
['site-weather-update',4,'Schimbarea programului din cauza vremii','Ești muncitorul. Nora coordonează programul. S-a anunțat vreme nefavorabilă, dar planul actualizat nu este aprobat. Nu decide măsuri tehnice.','Været kan påvirke planen, men jeg har ikke fått en godkjent oppdatering.','Kan du avklare dagens plan?','be ansvarlig bekrefte planen','vente på godkjent beskjed','Er endringen godkjent?','Nei, det må avklares.'],
['site-handover-incomplete',4,'Predarea unei lucrări neverificate','Ești muncitorul. Nora preia informațiile. Partea A este terminată, dar verificarea finală nu este făcută.','Del A er utført, men sluttkontrollen mangler.','Kan vi registrere statusen tydelig?','notere utført arbeid og manglende kontroll','be kontrollansvarlig følge opp','Er kontrollen gjennomført?','Nei, den gjenstår.'],
['site-two-crews',4,'Două echipe în același spațiu','Ești coordonatorul unei echipe. Nora coordonează cealaltă. Ambele au programat zona B; accesul comun nu este confirmat.','Begge teamene har planlagt arbeid i sone B.','Kan vi avklare rekkefølgen med ansvarlig?','be om en felles plan','be om separate tidspunkter','Er samtidig tilgang avklart?','Nei, det må ansvarlig vurdere.'],
['site-extra-request',4,'O sarcină suplimentară','Ești muncitorul. Nora coordonează echipa. Pe lângă sarcina A apare B, fără actualizarea timpului alocat.','Oppgave B er lagt til, men tiden er ikke justert.','Kan vi avklare prioriteringen?','prioritere den avtalte oppgaven A','be om en oppdatert plan for begge','Er den nye planen bekreftet?','Nei, vi må avklare den.']
],
healthcare: [
['care-new-colleague',1,'Prezentarea în echipa de sprijin','Ești noul coleg Alex. Nora coordonează activitățile neclinice. Prezintă-te și cere să vezi biroul.','Jeg heter Alex og er ny i støtteteamet.','Kan du vise meg kontoret?','gå til kontoret sammen','se plasseringen på et kart','Er dette kontoret til teamet?','Ja, teamet bruker dette kontoret.'],
['care-reading-glasses',1,'Unde sunt ochelarii?','Ești persoana asistată. Nora oferă sprijin neclinic. Nu găsești ochelarii de citit și ceri ajutor să îi cauți.','Jeg finner ikke lesebrillene mine.','Kan du hjelpe meg å lete?','se på bordet','se i den avtalte skuffen','Kan vi se på bordet først?','Ja, vi kan begynne der.'],
['care-blanket',1,'O pătură în plus','Ești persoana asistată. Nora oferă sprijin neclinic. Dorești o pătură suplimentară pentru confort.','Jeg ønsker et ekstra teppe.','Kan du hente et teppe?','hente et teppe nå','legge fram et teppe til senere','Kan du legge det på stolen?','Ja, det kan jeg.'],
['care-common-room',1,'Drumul spre sala comună','Ești vizitatorul. Nora oferă informații. Sala comună este lângă recepție în această clădire fictivă.','Jeg leter etter fellesrommet.','Kan du vise meg veien?','følge skiltene ved resepsjonen','be Nora peke ut rommet','Ligger det ved resepsjonen?','Ja, det ligger der.'],
['care-phone-call',2,'Ora unui apel','Ești persoana asistată. Nora ajută la organizare. Dorești un apel fictiv cu familia la 14 sau 16.','Jeg vil gjerne ringe familien.','Kan vi avtale et tidspunkt?','planlegge samtalen klokka fjorten','planlegge samtalen klokka seksten','Passer klokka fjorten?','Ja, vi kan planlegge det.'],
['care-activity-choice',2,'Alegerea unei activități','Ești participantul. Nora organizează activități neclinice. Poți alege lectură sau muzică în sala comună.','Jeg vil gjerne være med på en aktivitet.','Kan vi velge mellom lesing og musikk?','delta på lesestunden','delta på musikkstunden','Er lesestunden i fellesrommet?','Ja, den er der.'],
['care-visitor-time',2,'Când vine vizitatorul?','Ești persoana asistată. Nora coordonează vizitele. Vizitatorul fictiv a propus 15 sau 17; nimic nu este confirmat.','Vi har forslag om besøk klokka femten eller sytten.','Kan vi avklare tiden?','be om bekreftelse på femten','be om bekreftelse på sytten','Har besøkeren bekreftet tiden?','Nei, ikke ennå.'],
['care-room-preference',2,'Preferința pentru liniște','Ești participantul la o activitate. Nora o organizează. Preferi un loc liniștit și poți sta lângă fereastră sau lângă ușă.','Jeg ønsker en rolig plass.','Kan vi velge hvor jeg sitter?','sitte ved vinduet','sitte ved døren','Er plassen ved vinduet ledig?','Ja, den er ledig.'],
['care-missing-belonging',3,'O carte nu se găsește','Ești persoana asistată. Nora oferă sprijin. Cartea ta nu este la locul obișnuit; nu știi cine a mutat-o.','Boka mi ligger ikke på den vanlige plassen.','Kan vi undersøke hvor den er?','se på den avtalte bokhyllen','spørre teamet om boka er flyttet','Skal vi spørre teamet før vi antar noe?','Ja, vi kan spørre.'],
['care-message-repeat',3,'Mesajul nu a fost înțeles','Ești persoana asistată. Nora organizează activitățile. Ai auzit că programul s-a schimbat, dar nu ai înțeles noua oră.','Jeg hørte at planen er endret, men fikk ikke med meg tiden.','Kan du forklare endringen?','be om en langsom forklaring','be om en skriftlig beskjed','Kan du si tidspunktet en gang til?','Ja, vi går gjennom den bekreftede planen sammen.'],
['care-appointment-note',3,'Două ore pe bilețel','Ești persoana asistată. Nora ajută la organizarea unei vizite neclinice. Pe notițe apar orele 10 și 11.','Notatene viser både ti og elleve.','Kan vi sjekke riktig avtaletid?','kontrollere den siste bekreftelsen','kontakte den som avtalte besøket','Er den siste bekreftelsen tilgjengelig?','Vi må undersøke det.'],
['care-light-request',3,'Lumina este prea puternică','Ești persoana asistată. Nora oferă sprijin neclinic. Lumina te deranjează la lectură; ceri o schimbare simplă.','Lyset er for sterkt for meg når jeg leser.','Kan vi justere lyset?','dempe lampen hvis den kan reguleres','velge en annen tilgjengelig leseplass','Kan lampen reguleres?','Det må vi kontrollere før vi lover det.'],
['care-family-update',4,'Ce putem spune familiei?','Ești membrul echipei de sprijin. Nora coordonează activitățile. O activitate a fost planificată, dar participarea nu este confirmată. Nu transmite date medicale.','Aktiviteten er planlagt, men deltakelse er ikke bekreftet.','Kan vi formulere en presis oppdatering?','opplyse at aktiviteten er planlagt','vente på bekreftet deltakelse','Er deltakelsen dokumentert?','Nei, den er ikke bekreftet.'],
['care-choice-respect',4,'Preferința participantului','Ești membrul echipei de sprijin. Nora coordonează activitatea. Participantul fictiv preferă lectură, iar planul propune muzică.','Deltakeren foretrekker lesing, mens planen foreslår musikk.','Kan vi avklare ønsket før vi bestemmer?','bekrefte deltakerens ønske','undersøke en alternativ lesestund','Skal deltakeren få bekrefte ønsket selv?','Ja, vi spør deltakeren.'],
['care-support-handover',4,'Predarea unei solicitări','Ești membrul echipei de sprijin. Nora preia tura. A fost cerută o carte, dar nu s-a confirmat aducerea ei.','En bok er etterspurt, men levering er ikke bekreftet.','Kan du følge opp ønsket?','overlevere et skriftlig notat','avklare status med kollegaen','Skal ønsket stå som uavklart?','Ja, til det er fulgt opp.'],
['care-activity-cancelled',4,'Activitatea se amână','Ești organizatorul unei activități neclinice. Nora este participantă. Sala nu este disponibilă și noua dată nu este stabilită.','Rommet er ikke tilgjengelig, og ny dato er ikke bestemt.','Kan vi avtale hvordan du får oppdateringen?','gi beskjed når ny dato er bekreftet','undersøke et annet tilgjengelig rom','Er en ny dato allerede bekreftet?','Nei, det er den ikke.']
]
});


